import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;
import org.eclipse.rdf4j.query.parser.ParsedTupleQuery;
import org.junit.jupiter.api.Test;

class WindowFunctionParserTest {

	private static final String PREFIX = "PREFIX winf: <http://rdf4j.org/function/window#> PREFIX ex: <http://ex/> ";

	private static TupleExpr parse(String query) {
		TupleExpr expr = ((ParsedTupleQuery) new SPARQLParser().parseQuery(PREFIX + query, null)).getTupleExpr();
		return expr instanceof QueryRoot root ? root.getArg() : expr;
	}

	private static List<Window> windows(TupleExpr expr) {
		List<Window> windows = new ArrayList<>();
		expr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Window node) {
				windows.add(node);
				super.meet(node);
			}
		});
		return windows;
	}

	private static List<FunctionCall> functionCalls(TupleExpr expr) {
		List<FunctionCall> calls = new ArrayList<>();
		expr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(FunctionCall node) {
				calls.add(node);
				super.meet(node);
			}
		});
		return calls;
	}

	@Test
	void loweringOfFullSpecification() {
		TupleExpr expr = parse("SELECT ?x (winf:rank(winf:partitionBy(?d), winf:orderBy(winf:desc(?s), ?x),"
				+ " winf:rows(-1, \"current\")) AS ?r) WHERE { ?x ex:d ?d ; ex:s ?s }");
		List<Window> windows = windows(expr);
		assertThat(windows).hasSize(1);
		Window window = windows.get(0);
		assertThat(window.getElements()).hasSize(1);
		WindowFunctionCall call = window.getElements().get(0).getOperator();
		assertThat(call.getURI()).isEqualTo(WINF.RANK.stringValue());
		assertThat(call.getArgs()).isEmpty();
		assertThat(call.getPartitionBy()).hasSize(1);
		assertThat(((Var) call.getPartitionBy().get(0)).getName()).isEqualTo("d");
		assertThat(call.getOrderBy()).hasSize(2);
		assertThat(call.getOrderBy().get(0).isAscending()).isFalse();
		assertThat(((Var) call.getOrderBy().get(0).getExpr()).getName()).isEqualTo("s");
		assertThat(call.getOrderBy().get(1).isAscending()).isTrue();
		assertThat(call.getFrameMode()).isEqualTo(WindowFunctionCall.FrameMode.ROWS);
		assertThat(call.getFrameStart()).isEqualTo(-1L);
		assertThat(call.getFrameEnd()).isEqualTo(0L);
		// no winf: function calls remain in the tree; the projection refers to the window result
		assertThat(functionCalls(expr)).isEmpty();
		assertThat(expr).isInstanceOf(Projection.class);
		assertThat(((Projection) expr).getArg()).isInstanceOf(Extension.class);
		assertThat(((Extension) ((Projection) expr).getArg()).getArg()).isSameAs(window);
		assertThat(window.getBindingNames()).contains("x", "d", "s", window.getElements().get(0).getName());
	}

	@Test
	void windowSitsAboveGroupAndBelowOrderBy() {
		TupleExpr expr = parse("SELECT ?d (SUM(?s) AS ?total) (winf:rank(winf:orderBy(winf:desc(SUM(?s)))) AS ?r)"
				+ " WHERE { ?x ex:d ?d ; ex:s ?s } GROUP BY ?d ORDER BY ?r");
		List<Window> windows = windows(expr);
		assertThat(windows).hasSize(1);
		Window window = windows.get(0);
		assertThat(window.getArg()).isInstanceOf(Group.class);
		assertThat(expr).isInstanceOf(Projection.class);
		assertThat(((Projection) expr).getArg()).isInstanceOf(Order.class);
		Group group = (Group) window.getArg();
		// the SUM inside the window ordering was lowered into the group as an anonymous aggregate
		assertThat(group.getGroupElements()).hasSize(2);
		WindowFunctionCall call = window.getElements().get(0).getOperator();
		assertThat(call.getOrderBy()).hasSize(1);
		assertThat(call.getOrderBy().get(0).getExpr()).isInstanceOf(Var.class);
	}

	@Test
	void windowFunctionInsideLargerExpressionAndSharedWindow() {
		TupleExpr expr = parse(
				"SELECT (winf:rowNumber(winf:orderBy(?s)) * 10 AS ?a) (winf:lag(?s, 2, 0, winf:orderBy(?s)) AS ?b)"
						+ " WHERE { ?x ex:s ?s }");
		List<Window> windows = windows(expr);
		assertThat(windows).hasSize(1);
		assertThat(windows.get(0).getElements()).hasSize(2);
		WindowFunctionCall lag = windows.get(0).getElements().get(1).getOperator();
		assertThat(lag.getURI()).isEqualTo(WINF.LAG.stringValue());
		assertThat(lag.getArgs()).hasSize(3);
		assertThat(lag.getOrderBy()).hasSize(1);
		assertThat(lag.hasExplicitFrame()).isFalse();
		assertThat(windows.get(0)
				.getElements()
				.get(0)
				.getOperator()
				.sameWindowSpecification(lag)).isTrue();
	}

	@Test
	void unboundedFrameBoundsAndRange() {
		TupleExpr expr = parse(
				"SELECT (winf:sum(?s, winf:orderBy(?s), winf:range(\"unbounded\", \"current row\")) AS ?a)"
						+ " (winf:avg(?s, winf:rows(\"UNBOUNDED PRECEDING\", 2)) AS ?b) WHERE { ?x ex:s ?s }");
		List<WindowFunctionCall> calls = new ArrayList<>();
		windows(expr).get(0).getElements().forEach(e -> calls.add(e.getOperator()));
		assertThat(calls.get(0).getFrameMode()).isEqualTo(WindowFunctionCall.FrameMode.RANGE);
		assertThat(calls.get(0).getFrameStart()).isNull();
		assertThat(calls.get(0).getFrameEnd()).isEqualTo(0L);
		assertThat(calls.get(1).getFrameMode()).isEqualTo(WindowFunctionCall.FrameMode.ROWS);
		assertThat(calls.get(1).getFrameStart()).isNull();
		assertThat(calls.get(1).getFrameEnd()).isEqualTo(2L);
	}

	@Test
	void invalidSpecificationsAreRejected() {
		assertThatThrownBy(() -> parse("SELECT (winf:orderBy(?s) AS ?a) WHERE { ?x ex:s ?s }"))
				.isInstanceOf(MalformedQueryException.class);
		assertThatThrownBy(() -> parse("SELECT (winf:rank(winf:desc(?s)) AS ?a) WHERE { ?x ex:s ?s }"))
				.isInstanceOf(MalformedQueryException.class);
		assertThatThrownBy(() -> parse("SELECT (winf:rank(winf:rows(1)) AS ?a) WHERE { ?x ex:s ?s }"))
				.isInstanceOf(MalformedQueryException.class);
		assertThatThrownBy(() -> parse("SELECT (winf:rank(winf:rows(\"abc\", 1)) AS ?a) WHERE { ?x ex:s ?s }"))
				.isInstanceOf(MalformedQueryException.class);
		assertThatThrownBy(() -> parse("SELECT (winf:sum(winf:rank()) AS ?a) WHERE { ?x ex:s ?s }"))
				.isInstanceOf(MalformedQueryException.class);
		assertThatThrownBy(
				() -> parse("SELECT ?d (winf:rank(winf:orderBy(?s)) AS ?a) WHERE { ?x ex:d ?d ; ex:s ?s } GROUP BY ?d"))
						.isInstanceOf(MalformedQueryException.class);
	}

	@Test
	void windowFunctionInsideAggregateIsRejected() {
		// an aggregate is evaluated inside the Group, below the Window operator, so it could never see the window
		// result; the parser must reject the nesting instead of silently aggregating an unbound variable
		for (String query : List.of("SELECT (SUM(winf:rowNumber()) AS ?n) WHERE { ?x ex:s ?s }",
				"SELECT (1 + SUM(winf:rowNumber()) AS ?n) WHERE { ?x ex:s ?s }",
				"SELECT (COUNT(winf:rank(winf:orderBy(?s))) AS ?n) WHERE { ?x ex:s ?s }",
				"SELECT ?d (MAX(winf:rowNumber()) AS ?n) WHERE { ?x ex:d ?d ; ex:s ?s } GROUP BY ?d")) {
			assertThatThrownBy(() -> parse(query)).as(query)
					.isInstanceOf(MalformedQueryException.class)
					.hasMessageContaining("aggregate");
		}
	}

	@Test
	void windowReferencingSelectExpressionAliasIsRejected() {
		// a SELECT alias is bound above the Window operator, so a window keyed on it would silently see it unbound
		assertThatThrownBy(() -> parse(
				"SELECT (?s * 2 AS ?b) (winf:rank(winf:orderBy(?b)) AS ?r) WHERE { ?x ex:s ?s }"))
						.isInstanceOf(MalformedQueryException.class)
						.hasMessageContaining("variable 'b'");
		assertThatThrownBy(() -> parse(
				"SELECT (winf:sum(?b, winf:partitionBy(?s)) AS ?r) (?s + 1 AS ?b) WHERE { ?x ex:s ?s }"))
						.isInstanceOf(MalformedQueryException.class);
		assertThatThrownBy(() -> parse(
				"SELECT (winf:rowNumber() AS ?rn) (winf:sum(?rn) AS ?r) WHERE { ?x ex:s ?s }"))
						.isInstanceOf(MalformedQueryException.class);
	}

	@Test
	void windowFunctionOutsideSelectExpressionsIsRejected() {
		for (String query : List.of("SELECT ?a WHERE { ?x ex:s ?s BIND(winf:rowNumber() AS ?a) }",
				"SELECT ?x WHERE { ?x ex:s ?s FILTER(winf:rowNumber() > 0) }",
				"SELECT ?x WHERE { ?x ex:s ?s } ORDER BY winf:rank(winf:orderBy(?s))",
				"SELECT ?x (COUNT(?s) AS ?c) WHERE { ?x ex:s ?s } GROUP BY ?x HAVING (winf:rowNumber() > 1)",
				"SELECT ?k WHERE { ?x ex:s ?s } GROUP BY (winf:rowNumber() AS ?k)",
				"SELECT ?x WHERE { ?x ex:s ?s FILTER EXISTS { ?x ex:t ?t FILTER(winf:rowNumber() > 0) } }",
				"SELECT ?x WHERE { ?x ex:s ?s FILTER(winf:partitionBy(?s)) }")) {
			assertThatThrownBy(() -> parse(query)).as(query).isInstanceOf(MalformedQueryException.class);
		}
	}

	@Test
	void windowFunctionInUpdateWhereClauseIsRejected() {
		SPARQLParser parser = new SPARQLParser();
		assertThatThrownBy(() -> parser.parseUpdate(PREFIX
				+ "DELETE { ?x ex:s ?s } WHERE { ?x ex:s ?s FILTER(winf:rowNumber() > 0) }", null))
						.isInstanceOf(MalformedQueryException.class);
		assertThatThrownBy(() -> parser.parseUpdate(PREFIX
				+ "INSERT { ?x ex:n ?n } WHERE { ?x ex:s ?s BIND(winf:rowNumber() AS ?n) }", null))
						.isInstanceOf(MalformedQueryException.class);
		// a window function in a nested SELECT of an update is fine
		parser.parseUpdate(PREFIX + "INSERT { ?x ex:n ?n } WHERE { { SELECT ?x (winf:rowNumber(winf:orderBy(?s))"
				+ " AS ?n) WHERE { ?x ex:s ?s } } }", null);
	}

	@Test
	void nestedWindowFunctionsInsideSpecificationsAreRejected() {
		for (String select : List.of("(winf:sum(?s, winf:partitionBy(winf:rowNumber())) AS ?a)",
				"(winf:sum(?s, winf:partitionBy(winf:desc(?s))) AS ?a)",
				"(winf:rank(winf:orderBy(winf:rowNumber() + 0)) AS ?a)",
				"(winf:rank(winf:orderBy(STR(winf:rowNumber()))) AS ?a)",
				"(winf:sum(winf:rowNumber() * 1, winf:orderBy(?s)) AS ?a)",
				"(winf:lag(?s, winf:rowNumber(), winf:orderBy(?s)) AS ?a)")) {
			assertThatThrownBy(() -> parse("SELECT " + select + " WHERE { ?x ex:s ?s }")).as(select)
					.isInstanceOf(MalformedQueryException.class);
		}
	}

	@Test
	void frameBoundDirectionsMustMatchTheirPosition() {
		for (String frame : List.of("\"current\", \"unbounded preceding\"", "\"unbounded following\", \"current\"",
				"\"unbounded following\", \"unbounded following\"", "\"unbounded preceding\", \"unbounded preceding\"",
				"1, -1", "\"current row\", -1", "1, \"current row\"", "\"unbound\", 0", "0, \"currently\"")) {
			assertThatThrownBy(() -> parse("SELECT (winf:sum(?s, winf:orderBy(?s), winf:rows(" + frame
					+ ")) AS ?a) WHERE { ?x ex:s ?s }")).as(frame).isInstanceOf(MalformedQueryException.class);
		}
		TupleExpr expr = parse("SELECT (winf:sum(?s, winf:orderBy(?s), winf:rows(\"unbounded preceding\","
				+ " \"unbounded following\")) AS ?a) (winf:sum(?s, winf:orderBy(?s), winf:rows(\"current row\","
				+ " \"unbounded following\")) AS ?b) (winf:sum(?s, winf:orderBy(?s), winf:rows(-1, \"CURRENT ROW\"))"
				+ " AS ?c) WHERE { ?x ex:s ?s }");
		List<WindowFunctionCall> calls = new ArrayList<>();
		windows(expr).get(0).getElements().forEach(e -> calls.add(e.getOperator()));
		assertThat(calls.get(0).getFrameStart()).isNull();
		assertThat(calls.get(0).getFrameEnd()).isNull();
		assertThat(calls.get(1).getFrameStart()).isEqualTo(0L);
		assertThat(calls.get(1).getFrameEnd()).isNull();
		assertThat(calls.get(2).getFrameStart()).isEqualTo(-1L);
		assertThat(calls.get(2).getFrameEnd()).isEqualTo(0L);
	}

	@Test
	void windowNodeCloneAndEquality() {
		TupleExpr expr = parse(
				"SELECT (winf:rank(winf:partitionBy(?d), winf:orderBy(?s)) AS ?r) WHERE { ?x ex:d ?d ; ex:s ?s }");
		Window window = windows(expr).get(0);
		Window clone = window.clone();
		assertThat(clone).isEqualTo(window);
		assertThat(clone.hashCode()).isEqualTo(window.hashCode());
		assertThat(clone.getElements().get(0).getParentNode()).isSameAs(clone);
		assertThat(clone.getElements().get(0).getOperator().getParentNode()).isSameAs(clone.getElements().get(0));
		assertThat(clone.getSignature()).isEqualTo(window.getSignature());
	}
}
